head.script:
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gSelectedLdMktTpCd; // 선택된 법인의 시장코드

scwin.gIsurCd;
scwin.gMktTp;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        panel_debug.hide();
        btn_Delete_1.hide();
        btn_Delete_2.hide();
        btn_Delete_3.hide();
        btn_Delete_4.hide();
        btn_Delete_5.hide();
        txb_Chrg_ISUR_CD.hide();
        txb_LIST_STAT_CD.hide();
        txb_Krx_Emp_EMP_NO.hide();
        txb_Krx_Emp_DEP_CD.hide();
        txb_Chrg1_Chrg_Tp_Cd.hide();
        txb_Chrg1_Discls_Bz_Chrg_Assgn_Dd.hide();
        txb_Chrg2_Chrg_Tp_Cd.hide();
        txb_Chrg2_Discls_Bz_Chrg_Assgn_Dd.hide();
        txb_Chrg3_Chrg_Tp_Cd.hide();
        txb_Chrg3_Discls_Bz_Chrg_Assgn_Dd.hide();
        txb_Chrg4_Chrg_Tp_Cd.hide();
        txb_Chrg4_Discls_Bz_Chrg_Assgn_Dd.hide();
        txb_Chrg5_Chrg_Tp_Cd.hide();
        txb_Chrg5_Discls_Bz_Chrg_Assgn_Dd.hide();
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCodes();
        await scwin.getParentValue();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        scwin.init();
        if (cmb_LIST_STATUS.getValue() === "") {
            cmb_LIST_STATUS.setValue('Y');
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30633.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const ISUR_CD = $c.stf.getQuery(frame.srcUrl, "ISUR_CD"); // 다른 페이지(기업정보조회)에서 넘어오는 경우 처리.

    txb_ISUR_CD.setValue(ISUR_CD);
    chb_Grp_All.setValue(1); // 처음화면 로딩시 체크박스 전체를 TRUE 로 놓는다.

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_CorpInfo_onclick
 * @description 「회사정보」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_CorpInfo_onclick = async function() {
    try {
        if (txb_Corp_COM_NM.getValue() === "") {
            await $c.win.alert("회사를 선택하여 주십시오");
        } else {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30633.btn_CorpInfo_onclick" });
    }
};

