    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시책임자(유, 코)
    const sbmOptions3 = {
        id : "sbm_dts_Charge1_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Charge1_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시담당자1, 공시담당자(유, 코)
    const sbmOptions4 = {
        id : "sbm_dts_Charge2_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Charge2_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시담당자2, 공시실무자(유, 코)
    const sbmOptions5 = {
        id : "sbm_dts_Charge3_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Charge3_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    // TODO Stage2: sbmRtn5 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시대리인(유)
    const sbmOptions6 = {
        id : "sbm_dts_Charge4_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Charge4_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn6 = await $c.sbm.executeDynamic(sbmOptions6);
    // TODO Stage2: sbmRtn6 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (vMKT_TP_CD === '1') {
        // 공시담당보조자(유)
        const sbmOptions = {
            id : "sbm_dts_Charge5_Info",
            action : "/ListedCompany.do",
            ref : "",
            target : "dts_Charge5_Info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }

    // 삭제 버튼 노출여부 20180802
    if (txb_Chrg3_Chrg_Tp_Cd.getValue() !== "" && txb_Chrg3_Chrg_Tp_Cd.getValue().length > 0) btn_Delete_3.show("");

    else btn_Delete_3.hide();
    if (txb_Krx_Emp_DEP_CD.getValue() !== scwin.gDepCd && scwin.gDepCd !== "ZSYS" || txb_LIST_STAT_CD.getValue() !== "Y") {
        btn_Delete_3.hide();
    }

    // alert("gJobTitle : " + gJobTitle + " , " + "gDepCd : " + gDepCd+ " , " + "gEmpNo : " + gEmpNo + " , " + "gDutyGrp : " + gDutyGrp + " , " + "gDutyYn : " + gDutyYn + " , " + "gDutyChrg : " + gDutyChrg);

    const vStr = txb_Corp_CAP.getValue();
    if (vStr !== "") {
        vStr2 = $c.stf.FormatNumberEx(vStr);
        txb_Corp_CAP.setValue(vStr2);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {*} gbn gbn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(gbn) {
    let txb_Chrg_Chrg_Tp_Cd_value;
    let txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value;
    let txb_Chrg_CHRG_NM_value;
    let txb_Chrg_JOBTITL_NM_value;
    let del_msg;
    if (gbn === "3") {
        txb_Chrg_Chrg_Tp_Cd_value = txb_Chrg3_Chrg_Tp_Cd.getValue();
        txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value = txb_Chrg3_Discls_Bz_Chrg_Assgn_Dd.getValue();
        txb_Chrg_CHRG_NM_value = txb_Chrg3_CHRG_NM.getValue();
        txb_Chrg_JOBTITL_NM_value = txb_Chrg3_JOBTITL_NM.getValue();
    }
    if (scwin.gSelectedLdMktTpCd === "1") {
        del_msg = "공시담당자(부) ";
    } else {
        del_msg = "공시 실무자 ";
    }
    del_msg += txb_Chrg_CHRG_NM_value + " " + txb_Chrg_JOBTITL_NM_value + " 님을";
    const res = window.confirm(del_msg + " 삭제하시겠습니까?");
    if (res) {
        dts_Delete.removeAll();
        dts_Delete.insertRow();
        dts_Delete.setCellData(1, "ISUR_CD", scwin.gIsurCd);
        dts_Delete.setCellData(1, "CHRG_TP_CD", txb_Chrg_Chrg_Tp_Cd_value);
        dts_Delete.setCellData(1, "DISCLS_BZ_CHRG_ASSGN_DD", txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value);
        dts_Delete.setCellData(1, "TRANSTR_EMP_NO", scwin.gEmpNo);
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ListedCompany.do",
            ref : "dts_Delete",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    const arr = url.split("?");
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getParentValue = async function() {
    const pvd = scwin.getProvider();
    if (pvd !== null) {
        scwin.gMktTp = pvd.scwin.gMktTp;
        scwin.gIsurCd = pvd.scwin.gIsurCd;
        if ($c.ut.trim(scwin.gIsurCd).length === 5) {
            await scwin.initSearch();
        }
    }
};

/**
 * @method
 * @name initSearch
 * @description 다른창에서 담당종목 조회를 클릭할때
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function() {
    await scwin.getChargeIssue(scwin.gIsurCd, scwin.gMktTp);
};

/**
 * @method
 * @name readSecuChargeIssue
 * @description read Secu Charge Issue 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSecuChargeIssue = async function(GridID, row, colid) {
    if (row < 1) return;
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    let vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    scwin.gIsurCd = vISUR_CD; // 회사정보 팝업때문에
    const vMKT_TP_CD = objDataID.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD");
    scwin.gSelectedLdMktTpCd = vMKT_TP_CD; // 20180802

    await scwin.getChargeIssue(vISUR_CD, vMKT_TP_CD);
};

/**
 * @method
 * @name openResume
 * @description open Resume 처리
 * @returns {void}
 * @hidden N
 */
scwin.openResume = function() {
    $c.frame.path("../../").GWinOpen("ULDSTF30612", "/issueinfo/ULDSTF30612.gfm", "이력조회", 20, 20, 1270, 780, "");
};

/**
 * @method
 * @name FormatDateEx
 * @description Format Date Ex 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.FormatDateEx = function(str) {
    if (str === "") return "";
    return str.substring(0, 4) + "-" + str.substring(4, 6) + "-" + str.substring(6, 8);
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_Grp_St, chb_Grp_Mf, chb_Grp_Sc, chb_Grp_Rt, chb_Grp_Dr, chb_Grp_Fs, chb_Grp_If];
    if (chb_Grp_All.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
